import { Link, useParams } from "react-router-dom";
import { useTranslation } from "react-i18next";
import { Clock3, MapPin, MessageCircle, Phone, Package, Truck } from "lucide-react";
import { formatUZS } from "../data/mock";
import { useShop } from "../lib/store";
import { EmptyState, MapView, OrderProgress, OrderStatusBadge } from "../lib/ui";
import { BackButton } from "../components/BackButton";
export const TrackingPage = () => {
  const { t } = useTranslation();
  const { id } = useParams();
  const { orders, pushToast } = useShop();
  const order = orders.find((o) => o.id === id);
  if (!order) {
    return <div className="container-page py-16">
        <EmptyState
      icon={<Package size={28} />}
      title={t("emptyOrdersTitle")}
      description={t("emptyOrdersDesc")}
      action={<Link to="/orders" className="btn-primary btn-sm">{t("myOrders")}</Link>}
    />
      </div>;
  }
  return <div className="container-page py-5 sm:py-7">
      <div className="mb-4">
        <BackButton to="/orders" />
      </div>

      <div className="mb-5 flex flex-wrap items-end justify-between gap-2">
        <div>
          <h1 className="font-display text-2xl font-extrabold sm:text-3xl">{t("trackingTitle")}</h1>
          <p className="mt-1 text-xs text-[var(--muted)]">{t("trackingSubtitle")}</p>
        </div>
        <div className="flex items-center gap-2">
          <span className="font-display text-sm font-extrabold">#{order.id}</span>
          <OrderStatusBadge status={order.status} />
        </div>
      </div>

      <div className="grid gap-5 lg:grid-cols-[1.3fr_1fr]">
        <div className="card p-3 sm:p-4">
          <MapView courierName={order.courier} eta={order.eta ?? "25 daqiqa"} address={order.address} />
          <div className="mt-3 rounded-2xl bg-[var(--surface-2)] p-3">
            <div className="mb-2 flex items-center justify-between">
              <h2 className="text-xs font-extrabold">{t("orderProgress")}</h2>
              <span className="badge bg-brand-500/15 text-brand-700 dark:text-brand-300"><span className="h-1.5 w-1.5 animate-pulse rounded-full bg-brand-500" /> {t("liveTracking")}</span>
            </div>
            <OrderProgress status={order.status} />
          </div>
          <p className="mt-2 text-center text-[9px] text-[var(--muted)]">{t("mapNote")}</p>
        </div>

        <div className="space-y-3">
          <div className="card p-4">
            <h2 className="font-display text-base font-extrabold">{t("courier")}</h2>
            <div className="mt-3 flex items-center gap-3">
              <span className="flex h-12 w-12 items-center justify-center rounded-2xl bg-amber-400/20 text-2xl">🛵</span>
              <div className="flex-1">
                <p className="text-sm font-extrabold">{order.courier ?? "Jasur Toshmatov"}</p>
                <p className="text-[10px] font-bold text-[var(--muted)]">{t("courierOnWay")} · ⭐ 4.9</p>
              </div>
              <div className="text-right">
                <p className="text-[9px] font-bold text-[var(--muted)]">{t("estimatedArrival")}</p>
                <p className="font-display text-base font-extrabold text-brand-600 dark:text-brand-400">{order.eta ?? "25 daq"}</p>
              </div>
            </div>
            <div className="mt-3 flex gap-1.5">
              <a href="tel:+998901234567" className="btn-primary flex-1 btn-sm"><Phone size={13} /> {t("callCourier")}</a>
              <button onClick={() => pushToast("Chat demo rejimda ishlamoqda", "info")} className="btn-secondary flex-1 btn-sm"><MessageCircle size={13} /> {t("chat")}</button>
            </div>
          </div>

          <div className="card p-4">
            <h2 className="font-display text-base font-extrabold">{t("deliveryDetails")}</h2>
            <div className="mt-3 space-y-2.5 text-[11px]">
              <p className="flex items-start gap-2"><MapPin size={13} className="mt-0.5 shrink-0 text-brand-500" /><span className="text-[var(--muted)]">{order.address}</span></p>
              <p className="flex items-center gap-2"><Clock3 size={13} className="text-brand-500" /><span className="text-[var(--muted)]">{order.slot}</span></p>
              <p className="flex items-center gap-2"><Truck size={13} className="text-brand-500" /><span className="text-[var(--muted)]">{order.payment}</span></p>
            </div>
          </div>

          <div className="card p-4">
            <h2 className="font-display text-base font-extrabold">{t("yourOrder")}</h2>
            <div className="mt-3 space-y-2">
              {order.items.map((item, i) => <div key={`${item.productId}-${i}`} className="flex items-center gap-2">
                  <span className="flex h-8 w-8 items-center justify-center rounded-lg bg-[var(--surface-2)] text-base">{item.emoji}</span>
                  <div className="min-w-0 flex-1">
                    <p className="truncate text-[10px] font-extrabold">{item.name}</p>
                    <p className="text-[9px] text-[var(--muted)]">{item.qty} × {formatUZS(item.price)}</p>
                  </div>
                  <p className="text-[10px] font-extrabold">{formatUZS(item.price * item.qty)}</p>
                </div>)}
            </div>
            <div className="mt-3 flex items-center justify-between border-t pt-2.5">
              <span className="text-xs font-extrabold">{t("total")}</span>
              <span className="font-display text-lg font-extrabold text-brand-700 dark:text-brand-400">{formatUZS(order.total)}</span>
            </div>
          </div>

          <div className="rounded-2xl border border-dashed p-3 text-center">
            <p className="text-[10px] font-bold text-[var(--muted)]">{t("needHelp")}</p>
            <a href="tel:+998712000000" className="mt-1 inline-block text-xs font-extrabold text-brand-600 dark:text-brand-400">+998 71 200 00 00</a>
          </div>
        </div>
      </div>
    </div>;
};
